<script setup lang="ts">
import { onShow } from '@dcloudio/uni-app';import { ref } from 'vue';import { api } from '../../services/api';
const openPage = (url:string) => uni.navigateTo({url});
const data=ref<any>({counts:{},notices:[],tasks:[]});
async function load(){try{data.value=await api('/dashboard/management');}catch(e:any){uni.showModal({title:'加载失败',content:e.message??'请稍后重试',confirmText:'重试',success:(result:any)=>{if(result.confirm)load();}});}}
onShow(load);
</script>
<template><view class="page"><view class="actions"><button class="primary-btn" @tap="openPage('/pages/admin/create-notice')">发布通知</button><button class="secondary-btn" @tap="openPage('/pages/admin/create-task')">发布任务</button><button class="secondary-btn" @tap="openPage('/pages/admin/users')">人员管理</button><button class="secondary-btn" @tap="openPage('/pages/admin/audit')">操作日志</button></view><view class="metrics"><view><text>{{data.counts.pendingNotices??0}}</text><text>待确认</text></view><view><text>{{data.counts.pendingTasks??0}}</text><text>待完成</text></view><view><text>{{data.counts.pendingReviews??0}}</text><text>待审核</text></view><view><text class="danger">{{data.counts.overdue??0}}</text><text>逾期</text></view></view><text class="section-title">待跟进通知</text><view v-for="n in data.notices" :key="n.id" class="card row" @tap="openPage(`/pages/admin/notice-detail?id=${n.id}`)"><text>{{n.title}}</text><text class="danger">{{n.pending}} 人 ›</text></view><text class="section-title">待跟进任务</text><view v-for="t in data.tasks" :key="t.id" class="card row" @tap="openPage(`/pages/admin/task-detail?id=${t.id}`)"><text>{{t.title}}</text><text class="danger">待完成 {{t.pending}} · 待审核 {{t.pendingReview}} ›</text></view></view></template>
<style scoped>.actions{display:grid;grid-template-columns:1fr 1fr;gap:18rpx}.actions button{font-size:27rpx}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:16rpx;margin:28rpx 0}.metrics view{padding:28rpx;text-align:center;border-radius:22rpx;background:#fff}.metrics text{display:block}.metrics text:first-child{color:#007f95;font-size:44rpx;font-weight:800}.row{display:flex;justify-content:space-between;gap:20rpx}.row text:last-child{white-space:nowrap;font-size:24rpx}</style>
